---Indexes game files by lower-case path
local function byLowerPath(entries)
    local lowered = {}
    for path, entry in pairs(entries) do
        lowered[string.lower(path)] = entry
    end
    return lowered
end
RMS_StarterSoundsData.SOUNDS = byLowerPath(RMS_StarterSoundsData.SOUNDS)
RMS_StarterSoundsData.VEHICLES = byLowerPath(RMS_StarterSoundsData.VEHICLES)
